Hlp.UpdatePlayerPanel = function(panel) {
	var profile = GameApp.gm_ctx_.profile;
	var company = profile.selectedCompany();
	iriysoft_helper_Fwh.ChildGotoAndStop(panel,["mcPanel"],company.info().number() + 1);
	iriysoft_helper_Fwh.GetChildT(panel,["txtRankNum"]).set_text(Std.string(company.getRank()));
	iriysoft_helper_Fwh.GetChildT(panel,["txtEdictsNum"]).set_text(Std.string(company.getFreeSkillPoints()));
	var curVal = company.getCurXP();
	var maxVal = company.getNextXP();
	if(maxVal == 0) {
		iriysoft_helper_Fwh.GetChildT(panel,["txtXP"]).set_htmlText("<FONT COLOR='#FFFF00'> MAX RANK </FONT>");
	} else {
		iriysoft_helper_Fwh.GetChildT(panel,["txtXP"]).set_htmlText("<FONT COLOR='#FFFF00'>" + curVal + "</FONT><FONT COLOR='#DBDB02'> / " + maxVal + "</FONT>");
	}
	var progress_bar = iriysoft_helper_Fwh.GetChildA(panel,["mcXPIndicator","xp_bar_"]);
	progress_bar.stop();
	progress_bar.gotoFrame(Math.round(curVal * progress_bar.get_totalFrames() / maxVal + 1));
};
Hlp.getFormattedTimeBySeconds = function(time,use_hours,use_mins,use_secs_,use_millisecs) {
	var result = "";
	var seconds = Math.floor(time);
	var milliseconds = Math.floor(1000 * (time - seconds));
	var minutes = Math.floor(seconds / 60);
	seconds -= minutes * 60;
	var hours = Math.floor(minutes / 60);
	minutes -= hours * 60;
	if(use_hours) {
		result += hours;
	}
	if(use_mins) {
		if(use_hours) {
			result += ":";
			result += minutes < 10 ? "0" : "";
		}
		result += minutes;
	}
	if(use_secs_) {
		if(use_mins) {
			result += ":";
			result += seconds < 10 ? "0" : "";
		}
		result += seconds;
	}
	if(use_millisecs) {
		if(use_secs_) {
			result += ".";
			result += (milliseconds < 100 ? "0" : "") + (milliseconds < 10 ? "0" : "");
		}
		result += milliseconds;
	}
	return result;
};
