Hlp.ShowWindow = function(cont,back_,on_end) {
	cont.set_visible(true);
	back_.set_visible(true);
	var from_y = cont.get_y() + 50;
	var cont_alpha = cont.get_alpha();
	var back_alpha = back_ != null ? back_.get_alpha() : 0;
	motion_Actuate.update(function(v) {
		cont.set_y(from_y - v * 50);
		cont.set_alpha(cont_alpha * v);
		if(back_ != null) {
			back_.set_alpha(back_alpha * v);
		}
	},0.2,[0],[1]).ease(motion_easing_Quad.easeOut).onComplete(function() {
		if(on_end != null) {
			on_end(cont);
		}
	});
};
Hlp.HideWindow = function(cont,back_,on_end) {
	var end_y = cont.get_y();
	var cont_alpha = cont.get_alpha();
	var back_alpha = back_ != null ? back_.get_alpha() : 0;
	motion_Actuate.update(function(v) {
		cont.set_y(end_y + v * 50);
		cont.set_alpha(cont_alpha * (1 - v));
		if(back_ != null) {
			back_.set_alpha(back_alpha * (1 - v));
		}
	},0.2,[0],[1]).ease(motion_easing_Quad.easeIn).onComplete(function() {
		if(on_end != null) {
			on_end(cont);
		}
		cont.set_y(end_y);
		cont.set_alpha(cont_alpha);
		if(back_ != null) {
			back_.set_alpha(back_alpha);
		}
		cont.set_visible(false);
		back_.set_visible(false);
	});
};
