	,checkLevelCompleteStatus: function(_missionStats) {
		var time = Math.floor(_missionStats.missionTime);
		if(_missionStats.missionOverStatus == battle_stat_MissionStats.MISSION_COMPLETE) {
			if(time <= this.getGoldTime()) {
				return 3;
			}
			if(time <= this.getSilverTime()) {
				return 2;
			}
			return 1;
		}
		return 0;
	}
