		var _g1 = this.m_actionButtons.length;
		while(_g < _g1) {
			var i = _g++;
			var btn = this.m_actionButtons[i];
			var available = this.ref_level.buttonSpellIsAvailable(i);
			if(available) {
				if(!btn.get_enable()) {
					btn.set_enable(true);
				}
			} else if(btn.get_enable()) {
				btn.set_enable(false);
			}
			if(btn.get_enable()) {
				iriysoft_helper_Fwh.ButtonSetVisible(btn,"mcMana",true);
				iriysoft_helper_Fwh.ButtonSetVisible(btn,"mcIconSet",true);
			} else {
				iriysoft_helper_Fwh.ButtonSetVisible(btn,"mcMana",false);
				iriysoft_helper_Fwh.ButtonSetVisible(btn,"mcIconSet",false);
			}
		}
