	,createHintShowEffect: function(_hint,_enable) {
		if(_enable) {
			_hint.set_alpha(Math.max(0.1,_hint.get_alpha()));
			_hint.addEventListener("enterFrame",$bind(this,this.onShowHintEffectEneterFrame));
		} else {
			_hint.removeEventListener("enterFrame",$bind(this,this.onShowHintEffectEneterFrame));
		}
	}
	,createHintHideEffect: function(_hint,_enable) {
		if(_enable) {
			_hint.addEventListener("enterFrame",$bind(this,this.onHideHintEffectEneterFrame));
		} else {
			_hint.removeEventListener("enterFrame",$bind(this,this.onHideHintEffectEneterFrame));
		}
	}
	,onShowHintEffectEneterFrame: function(e) {
		var mc = e.target;
		var _g = mc;
		_g.set_alpha(_g.get_alpha() * 1.3);
		mc.set_alpha(Math.min(1,mc.get_alpha()));
		if(mc.get_alpha() == 1) {
			mc.removeEventListener("enterFrame",$bind(this,this.onShowHintEffectEneterFrame));
		}
	}
	,onHideHintEffectEneterFrame: function(e) {
		var mc = e.target;
		var _g = mc;
		_g.set_alpha(_g.get_alpha() / 1.3);
		mc.set_alpha(Math.max(0,mc.get_alpha()));
		if(mc.get_alpha() == 0) {
			mc.removeEventListener("enterFrame",$bind(this,this.onHideHintEffectEneterFrame));
		}
	}
