	,updateBuildingStat: function(_cmb) {
		if(_cmb == null) {
			return;
		}
		var keyNodes = this.findCombotantKeyNodes(_cmb.description);
		var locationNum;
		var buildPlaces;
		var goldSpeed = 0;
		var manaSpeed = 0;
		var supplyPower = 0;
		var armyPower = 0;
		var ultimateTimeSpeed = 0;
		var farmCounter = 0;
		var mineCounter = 0;
		var obeliskCounter = 0;
		var _g = 0;
		while(_g < keyNodes.length) {
			var kn = keyNodes[_g];
			++_g;
			if(kn.isActive()) {
				goldSpeed += kn.goldSpeed;
				manaSpeed += kn.manaSpeed;
				supplyPower += kn.supplyPower;
				ultimateTimeSpeed += kn.ultimateTimeSpeed;
			}
			locationNum = this.getNodes().getObject(kn.nodeDescription).locationNum;
			buildPlaces = this.findBuildPlaceByLocationNum(locationNum);
			var _g1 = 0;
			while(_g1 < buildPlaces.length) {
				var bp = buildPlaces[_g1];
				++_g1;
				goldSpeed += bp.goldSpeed;
				manaSpeed += bp.manaSpeed;
				supplyPower += bp.supplyPower;
				ultimateTimeSpeed += bp.ultimateTimeSpeed;
				switch(this.getBuildPlaceType(bp)._hx_index) {
				case 1:
					++farmCounter;
					break;
				case 2:
					++mineCounter;
					break;
				case 3:
					++obeliskCounter;
					break;
				default:
				}
			}
		}
		_cmb.setSupplyOwned(farmCounter,mineCounter,obeliskCounter);
		_cmb.setStat(goldSpeed,supplyPower,this.calcCombotantSquadsUpkeep(_cmb.description),manaSpeed,ultimateTimeSpeed);
	}
