		_keyNode.initByKeyNodeType(_keyNode.getNodeType(),newOwner);
		_keyNode.setHP(savedHP);
		_keyNode.owner = newOwner.description;
		this.updateCombotantsBuildingStat();
		var node = this.getNodes().getObject(_keyNode.nodeDescription);
		this.setLocationRace(node.locationNum,newOwner.getRace());
		newOwner.setKeyNodes(this.findCombotantKeyNodes(newOwner.description));
		prevOwner.setKeyNodes(this.findCombotantKeyNodes(prevOwner.description));
		this.clearBuildPlaces(_keyNode);
		this.checkWinLoose();
