	,processMainMouseController: function(_timeElapsed,_lock) {
		if(_lock == true) {
			return _lock;
		}
		if(this.mouseDevice().wasMoved()) {
			var ny = this.mouseDevice().y();
			ny *= 2;
			this.ref_rglObjectUnderCursor = this.rendBuff().findFirstHitTest(this.mouseDevice().x(),ny,3);
			this.m_levelMaskColorUnderCursor = this.getLevelMaskColorAt(this.mouseDevice().x() | 0,this.mouseDevice().y() | 0);
		}
		if(this.hasCursorIcon()) {
			if(this.mouseDevice().wasMoved()) {
				this.synhronizeCursorWithMouse();
			}
		}
		return _lock;
	}
	,selectCursorIcon: function(_id) {
		if(this.curCursorIcon() != null) {
			iriysoft_helper_Fwh.RemoveFromParent(this.curCursorIcon());
		}
		this.m_curIconID = _id;
		if(this.m_curIconID >= 0) {
			this.cursorIconLayer().addChild(this.curCursorIcon());
			this.synhronizeCursorWithMouse();
		}
	}
	,createIconCursor: function(_animKey) {
		if(_animKey == "") {
			this.m_cursorIconSet.push(null);
		} else {
			this.m_cursorIconSet.push(Hlp.FromScreensA(_animKey));
		}
		return this.m_cursorIconSet.length - 1;
	}
	,synhronizeCursorWithMouse: function() {
		var ny = this.mouseDevice().y();
		var pnt = this.cursorIconLayer().globalToLocal(new openfl_geom_Point(this.mouseDevice().x(),ny));
		this.curCursorIcon().set_x(pnt.x);
		this.curCursorIcon().set_y(pnt.y);
	}
