	,processNodeSelectorMouseController: function(_timeElapsed,_lock) {
		if(_lock == true) {
			this.ref_rglObjectUnderCursor = null;
			this.ref_selectedNodeContent = null;
			return _lock;
		}
		if(this.mouseDevice().wasMoved()) {
			this.rendBuff().allHighLightsOff(3);
			if(this.ref_rglObjectUnderCursor != null) {
				if(((this.ref_rglObjectUnderCursor) instanceof level_Chest)) {
					this.showChestHint(this.ref_rglObjectUnderCursor);
				} else {
					this.hideChestHint();
				}
				this.ref_rglObjectUnderCursor.set_highlight(true);
			} else {
				this.hideChestHint();
			}
			if(this.ref_selectedNodeContent != null) {
				this.ref_selectedNodeContent.set_highlight(true);
			}
		}
		if(this.mouseDevice().buttonWasClicked() && this.m_frameSelecRect.width < 1 && this.m_frameSelecRect.height < 1) {
			haxe_Log.trace("processNodeSelectorMouseController",{ fileName : "src/level/Level.hx", lineNumber : 954, className : "level.Level", methodName : "processNodeSelectorMouseController", customParams : [this.m_frameSelecRect]});
			if(this.ref_selectedNodeContent != null) {
				this.ref_selectedNodeContent.set_highlight(false);
			}
			if(((this.ref_rglObjectUnderCursor) instanceof level_NodeContent)) {
				this.ref_selectedNodeContent = this.ref_rglObjectUnderCursor;
			} else {
				this.ref_selectedNodeContent = null;
			}
			if(this.ref_selectedNodeContent != null && level_LevelVisual.checkMode(4)) {
				var plr = this.seekNodeContentOwner((js_Boot.__cast(this.ref_selectedNodeContent , level_NodeContent)).nodeDescription);
				if(plr != null) {
					this.m_def.player = plr;
				}
			}
			this.signalSelectNodeContent_.emit(this.ref_selectedNodeContent);
		}
		return _lock;
	}
	,resetNodeSelectorMouseController: function() {
		if(this.ref_selectedNodeContent != null) {
			this.ref_selectedNodeContent.set_highlight(false);
		}
		this.ref_selectedNodeContent = null;
	}
