	,processSpellNodeController: function(_timeElapsed,_lock) {
		if(_lock == true) {
			this.selectCursorIcon(-1);
			return _lock;
		}
		if(this.m_enableSpellController == false) {
			return false;
		}
		if(this.mouseDevice().wasMoved()) {
			this.synhronizeSpellPosition();
		}
		if(this.mouseDevice().buttonWasClicked() && this.isSpellCursorEnable()) {
			this.castSpell(this.m_curSpell,this.player());
			this.disableSpellMode();
		}
		if(level_Level.isCursorUnderButton) {
			this.selectCursorIcon(-1);
		}
		return true;
	}
